/// The click sounds people can pick. All but `pop` are generated by `ClickSynth`;
/// `pop` is the macOS system sound.
public enum ClickSoundKind: String, CaseIterable, Sendable {
    case tap, tick, knock, boop, pop

    public var title: String {
        switch self {
        case .tap: return "Tap"
        case .tick: return "Tick"
        case .knock: return "Knock"
        case .boop: return "Boop"
        case .pop: return "Pop"
        }
    }
}

/// The click sound's saved settings. Like `PointerSettings`, every read validates what's
/// stored and falls back to the default.
public final class SoundSettings {
    public static let volumeRange: ClosedRange<Double> = 0...1
    public static let defaultVolume = 0.47

    private let store: SettingsStore

    public init(store: SettingsStore) { self.store = store }

    private enum Key {
        static let isOn = "sound"  // from the proof of concept
        static let volume = "soundVolume"
        static let kind = "soundKind"
        static let quieterWhenFast = "soundQuieterWhenFast"
        static let followsMood = "soundFollowsMood"
    }

    public var isOn: Bool {
        get { store.object(forKey: Key.isOn) as? Bool ?? true }
        set { store.set(newValue, forKey: Key.isOn) }
    }

    /// Slider position, 0…1. `ClickSoundMix` turns it into a gain.
    public var volume: Double {
        get {
            guard let v = store.object(forKey: Key.volume) as? Double, v.isFinite else {
                return Self.defaultVolume
            }
            return v.clamped(to: Self.volumeRange)
        }
        set {
            let v = newValue.isFinite ? newValue.clamped(to: Self.volumeRange) : Self.defaultVolume
            store.set(v, forKey: Key.volume)
        }
    }

    public var kind: ClickSoundKind {
        get { (store.object(forKey: Key.kind) as? String).flatMap(ClickSoundKind.init) ?? .tap }
        set { store.set(newValue.rawValue, forKey: Key.kind) }
    }

    public var quieterWhenFast: Bool {
        get { store.object(forKey: Key.quieterWhenFast) as? Bool ?? true }
        set { store.set(newValue, forKey: Key.quieterWhenFast) }
    }

    public var followsMood: Bool {
        get { store.object(forKey: Key.followsMood) as? Bool ?? true }
        set { store.set(newValue, forKey: Key.followsMood) }
    }

    /// The loudness and pitch rules for the current settings.
    public var mix: ClickSoundMix {
        ClickSoundMix(volume: volume, quieterWhenFast: quieterWhenFast, followsMood: followsMood)
    }
}
